/** Grounded learning activities and answer-free student hints generated by local rules. */
import { effectiveScore, effectiveMax, effectiveTopic, get_student_stats } from '../data/core.ts'
import type { CsvRow, PreparedDataset, ResultEnvelope, StudentScope, StudentStats } from '../data/types.ts'
import { diagnose_student } from '../diagnosis/core.ts'
import type { DiagnosisPayload, Finding } from '../diagnosis/core.ts'
import { INDICATOR_GUIDANCE, guidance_for } from './knowledge.ts'
import type { EvidenceGap, HintPayload, HintRequest, LearningActivity, LearningPlanPayload, PlanCertainty } from './types.ts'

function result<T>(
  dataset: PreparedDataset, scope: Record<string, string | boolean>, payload: T,
  status: ResultEnvelope<T>['result_status'], evidence: string[], limitations: string[],
): ResultEnvelope<T> {
  return {
    schema_version: dataset.schema_version, generated_at: dataset.generated_at, dataset_version: dataset.dataset_version, policy_version: dataset.policy_version,
    producer_version: dataset.producer_version, source_mode: dataset.source_mode, scope, result_status: status,
    payload, evidence_ids: [...new Set(evidence)].sort(), limitations,
  }
}

function ids(text: string | undefined): string[] {
  return text?.split(/[、,，;；\s]+/u).filter(Boolean) ?? []
}

function normalize(text: string): string {
  return text.normalize('NFKC').replace(/\s/gu, '').replace(/[−﹣]/gu, '-')
}

/** Return whether a student hint copies an answer fragment or states the question's conclusion. */
export function hint_leaks_answer(hint: string, answer: string): boolean {
  const normalizedHint = normalize(hint).toLowerCase()
  const normalizedAnswer = normalize(answer).toLowerCase()
  if (!normalizedHint || !normalizedAnswer) return false
  if (/^(?:答案|参考答案)[:：]/u.test(hint.trim())) return true
  if (/^\p{Script=Han}$/u.test(normalizedAnswer) && normalizedHint.includes(normalizedAnswer)) return true
  const fragments = [normalizedAnswer]
  for (const segment of normalizedAnswer.split(/[；;。，,\n]+/u)) {
    fragments.push(segment.replace(/^(?:参考)?答案[:：]?/u, '').replace(/^(?:答|结果|结论)[:：]?/u, ''))
  }
  for (const match of normalizedAnswer.matchAll(/[-]?\d+(?:\.\d+)?/gu)) {
    if (match[0].length >= 2) fragments.push(match[0])
  }
  if (fragments.some(fragment => fragment.length >= 2 && normalizedHint.includes(fragment))) return true
  if (/^[a-d]$/u.test(normalizedAnswer) && /(?:答案(?:是|为)?|应选|选)[a-d]/iu.test(normalizedHint)) return true
  return [
    /(?:所以|因此|可知|可见).*(?:正确|错误|恒等|等于|为|不变|无关|成立|不成立)/u,
    /(?:恒等于|恒为|对所有.+都不变|与.+取值无关|说法(?:正确|错误))/u,
    /(?:结果|结论)(?:是|为)(?:[-]?\d|[a-z]|.{0,10}(?:不变|无关|正确|错误))/u,
    /(?:应选|选)[a-d]/iu,
  ].some(pattern => pattern.test(normalizedHint))
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0
}

function skillFamily(item: CsvRow | undefined, requirement: CsvRow | undefined): 'inequality' | 'equation' | 'algebra' | 'general' {
  const description = `${item?.['题干或内容'] ?? ''} ${requirement?.['主题'] ?? ''} ${requirement?.['观察指标'] ?? ''}`
  if (/不等式|解集|[<>≤≥]/u.test(description)) return 'inequality'
  if (/方程|消元|等式/u.test(description)) return 'equation'
  if (/代数式|整式|同类项|去括号/u.test(description)) return 'algebra'
  return 'general'
}

function methodHint(family: ReturnType<typeof skillFamily>, level: 1 | 2 | 3): string {
  const hints = {
    inequality: [
      '先找出不等关系和未知量，检查准备对两边进行什么运算。',
      '每做一次两边同乘或同除，先判断所用数的正负，再决定不等号方向。',
      '两边同乘或同除负数时，不等号必须反向；再核对端点和公共解集，先修正最早的一步，再继续推导。',
    ],
    equation: [
      '先标出已知量、未知量和相等关系，说明为什么可以这样列式。',
      '变形时说明等式两边做了相同的运算；有多个未知量时，先选择要消去的量。',
      '逐步核对去括号、移项和合并的理由，再把得到的结果代回原关系检查；先修正最早的不一致。',
    ],
    algebra: [
      '先说明字母表示的量，再识别各项和它们之间的运算关系。',
      '代入时保留数的符号并加括号；化简时先检查括号前符号，再判断哪些项可以合并。',
      '为每次去括号和合并写下依据，逐项核对符号、字母和指数；用一个自选的数检查变形前后是否一致。',
    ],
    general: [
      '先读题并标出已知条件、要解决的问题和准备使用的规则。',
      '把解题任务拆成可以检查的小步骤，每步说明使用了哪个条件。',
      '逐步核对运算和理由，先修正最早发现的不一致，再用题目条件检查得到的结果。',
    ],
  }
  return hints[family][level - 1]!
}

function focusedHint(item: CsvRow, requirement: CsvRow | undefined, level: 1 | 2 | 3): string {
  const indicatorId = item['指标编号']
  const indicatorGuidance = indicatorId && Object.hasOwn(INDICATOR_GUIDANCE, indicatorId)
    ? INDICATOR_GUIDANCE[indicatorId]
    : undefined
  if (indicatorGuidance) return indicatorGuidance.hints[level - 1]!
  const text = `${item['题干或内容'] ?? ''} ${requirement?.['观察指标'] ?? ''}`
  const hints = /方程组|消元|二元/u.test(text) ? [
    '先确认各未知量和每个等式的含义，选一个准备消去的未知量。',
    '比较代入和加减两种消元方法，说明怎样使同一未知量的系数便于相消。',
    '消去一个未知量后再求另一个；将得到的一组值代回所有原等式逐一核对，不只检查其中一个。',
  ] : /不等式组|公共解集|数轴/u.test(text) ? [
    '先分别理解每个不等式的条件，明确最后需要同时满足哪些条件。',
    '分别求出各条件的范围，在数轴上标清端点是否包含，再找它们的重合部分。',
    '逐一核对端点、方向和公共部分；取范围内外的数检查是否同时满足所有原条件。',
  ] : /实际|建模|至少|至多|不超过|数量关系/u.test(text) ? [
    '先说明未知量及单位，按题意逐项列出数量关系和限制条件。',
    '判断每条关系应使用相等还是不等符号，解释为什么该式能表达题目条件。',
    '求得结果后回到原情境，核对单位、取值限制和每条原条件；发现不一致时先修正列式。',
  ] : /代入|求值/u.test(text) ? [
    '先辨认要代入的字母和它的取值，保留原式的运算顺序。',
    '把给定的数连同正负号一起代入，必要时加括号，再按运算顺序计算。',
    '逐项核对是否漏代字母或改变符号，再检查乘方、乘除和加减的先后；可以保留中间式供教师查看。',
  ] : null
  return hints?.[level - 1] ?? methodHint(skillFamily(item, requirement), level)
}

function sameVersion(dataset: PreparedDataset, output: ResultEnvelope<unknown>): boolean {
  return output.schema_version === dataset.schema_version && output.dataset_version === dataset.dataset_version
    && output.policy_version === dataset.policy_version && output.producer_version === dataset.producer_version
    && output.source_mode === dataset.source_mode && output.generated_at === dataset.generated_at
}

/**
 * Build targeted, extension or observation activities from valid evidence in one test.
 * @param dataset - Prepared source snapshot; questionable scoring remains excluded.
 * @param scope - Student and test identifiers, both required.
 * @param diagnosis - Optional diagnosis from the same versions and scope; omitted values are computed locally.
 * @param statistics - Optional same-snapshot statistics reused by an orchestrator.
 * @returns A plan containing only available materials and test-appropriate practice.
 */
export function build_learning_plan(
  dataset: PreparedDataset, scope: StudentScope,
  diagnosis: ResultEnvelope<DiagnosisPayload> = diagnose_student(dataset, scope),
  statistics: ResultEnvelope<StudentStats> = get_student_stats(dataset, scope),
): ResultEnvelope<LearningPlanPayload> {
  const statisticsMatch = sameVersion(dataset, statistics)
    && statistics.payload.student_id === scope.student_id && statistics.payload.node_id === scope.node_id
    && statistics.scope['student_id'] === scope.student_id && statistics.scope['node_id'] === scope.node_id
  const stats = statisticsMatch ? statistics : get_student_stats(dataset, scope)
  const payload: LearningPlanPayload = {
    engine: 'local_rules', ...scope, plan_type: 'blocked', diagnosis_status: diagnosis.result_status,
    certainty: 'insufficient', summary: '计划尚未生成，需先核对统计和诊断状态。', evidence_gaps: [],
    statistics: stats.payload, activities: [], review_record_ids: stats.payload.review_record_ids,
    delivery: {
      first_activity_ids: [], follow_up_activity_ids: [], first_batch_limit: 3,
      advance_when: '先完成本轮任务并保留独立作答、提示等级与评分，再由教师核对是否进入后续活动；不以点击完成代替新证据。',
    },
  }
  if (!statisticsMatch) return result(dataset, { ...scope }, payload, 'error', stats.evidence_ids, ['统计上下文的版本或学生、节点与当前请求不一致，未复用其他对象的统计。'])
  if (stats.result_status === 'error' || diagnosis.result_status === 'error') {
    return result(dataset, { ...scope }, payload, 'error', stats.evidence_ids, [
      '统计或诊断未能完成，已保留可用统计事实，暂不生成个性化活动。', ...stats.limitations, ...diagnosis.limitations,
    ])
  }
  if (!sameVersion(dataset, diagnosis) || diagnosis.payload.student_id !== scope.student_id || diagnosis.payload.node_id !== scope.node_id
    || diagnosis.scope['student_id'] !== scope.student_id || diagnosis.scope['node_id'] !== scope.node_id) {
    return result(dataset, { ...scope }, payload, 'error', stats.evidence_ids, ['诊断的数据版本、策略、生产者、来源或对象范围与当前请求不一致，未拼接计划。'])
  }
  const reviewIds = new Set([...stats.payload.review_record_ids, ...diagnosis.payload.findings
    .filter(finding => finding.category === 'scoring_review').flatMap(finding => finding.evidence_ids)])
  payload.review_record_ids = [...reviewIds].sort()
  const node = dataset.input.nodes.find(row => row['节点编号'] === scope.node_id)!
  const allowedItems = new Set(ids(node['可用题目编号']))
  const taughtTopics = new Set(ids(node['已教及测量主题']))
  const items = dataset.input.items.filter(item => item['材料类型'] === '题目' && allowedItems.has(item['材料编号'] ?? '')
    && taughtTopics.has(item['主题编号'] ?? ''))
  const valid = dataset.current.filter(record => record.student_id === scope.student_id && record.node_id === scope.node_id
    && record.include_in_statistics && !reviewIds.has(record.record_id))
  const itemIndicators = new Map(items.map(item => [item['材料编号'], item['指标编号']]))
  const scoredIndicators = dataset.input.requirements.map(requirement => {
    const records = valid.filter(record => itemIndicators.get(record.item_id) === requirement['指标编号'])
    return {
      indicator_id: requirement['指标编号'], valid_record_count: records.length,
      earned_score: records.reduce((sum, record) => sum + effectiveScore(record)!, 0),
      possible_score: records.reduce((sum, record) => sum + effectiveMax(record)!, 0),
      evidence_ids: records.map(record => record.record_id).sort(),
    }
  }).filter(indicator => indicator.valid_record_count > 0)
  const missingTaughtTopic = [...taughtTopics].some(topic => !valid.some(record => effectiveTopic(record) === topic))
  const hasPartial = valid.some(record => effectiveScore(record) !== null && effectiveMax(record) !== null && effectiveScore(record)! < effectiveMax(record)!)
  const planType = hasPartial ? 'targeted_practice' : valid.length === 0 || missingTaughtTopic ? 'observation' : 'extension'
  payload.plan_type = planType
  const limitations = ['本计划由本地规则生成，未调用远程大模型；建议依据指定节点已有表现，不代表真实教学成效。', '活动顺序、首轮上限、证据充分度和调整条件均为团队实施规则，不是官方标准或教育学定论。']
  const ordered = [...dataset.input.requirements].sort((a, b) => compareText(a['指标编号'] ?? '', b['指标编号'] ?? ''))
  const evidenceGaps: EvidenceGap[] = ordered.filter(requirement => taughtTopics.has(requirement['主题编号'] ?? '')
    && !scoredIndicators.some(indicator => indicator.indicator_id === requirement['指标编号']))
    .map(requirement => ({ indicator_id: requirement['指标编号']!, topic_id: requirement['主题编号']!, reason: '该已教指标在当前节点没有可用于本计划的已评分证据，先补充观察，不判定未掌握。' }))
  payload.evidence_gaps = evidenceGaps
  const certainty: PlanCertainty = valid.length === 0 ? 'insufficient'
    : planType === 'observation' || valid.length < 3 ? 'provisional' : 'adequate'
  payload.certainty = certainty
  payload.summary = planType === 'targeted_practice'
    ? `当前节点有 ${valid.length} 条有效证据，优先处理出现失分的指标，并按顺序完成复盘、练习与检查。`
    : planType === 'extension'
      ? '在已有有效表现的范围安排解释、检验和迁移；未覆盖的已教指标另行补充观察，不推断长期掌握。'
      : '当前节点证据不足或存在未覆盖的已教指标，先补充观察，不把缺记录解释为未掌握。'
  const priorities: Array<{ requirement: CsvRow; kind: LearningActivity['kind']; evidence: string[]; rationale: string; findings: Finding[]; score_rate: number | null }> = []
  for (const requirement of ordered) {
    const indicatorId = requirement['指标编号'] ?? ''
    const topicId = requirement['主题编号'] ?? ''
    if (!taughtTopics.has(topicId) || !items.some(item => item['指标编号'] === indicatorId)) continue
    const observed = scoredIndicators.find(indicator => indicator.indicator_id === indicatorId)
    if (!observed) {
      priorities.push({ requirement, kind: 'observation', evidence: [], rationale: '该节点的这个指标缺少有效作答，只安排补充观察，不判定未掌握。', findings: [], score_rate: null })
    } else if (observed.earned_score !== null && observed.possible_score !== null && observed.earned_score < observed.possible_score) {
      const supported = diagnosis.payload.findings.filter(finding => finding.indicator_id === indicatorId
        && finding.category !== 'scoring_review' && finding.category !== 'insufficient_data'
        && finding.evidence_ids.every(id => !reviewIds.has(id)))
      priorities.push({ requirement, kind: 'targeted_practice', evidence: observed.evidence_ids, findings: supported,
        score_rate: observed.earned_score / observed.possible_score,
        rationale: supported.length > 0 ? supported.map(finding => finding.description).join(' ') : '该指标已有有效记录出现失分，先核对作答与评分依据，再安排针对练习。' })
    } else {
      priorities.push({ requirement, kind: 'extension', evidence: observed.evidence_ids, rationale: '该指标已观察作答均获满分，可检验解释、检查和迁移能力；结论仅限已覆盖内容。', findings: [], score_rate: 1 })
    }
  }
  const hasLocatedError = (priority: typeof priorities[number]): boolean => priority.findings.some(finding => finding.category === 'fact' && finding.step_refs.length > 0 && finding.item_id !== null)
  const rank = (priority: typeof priorities[number]): number => hasLocatedError(priority) ? 0 : priority.kind === planType ? 1 : priority.kind === 'observation' ? 2 : 3
  priorities.sort((a, b) => rank(a) - rank(b) || (a.kind === 'targeted_practice' && b.kind === 'targeted_practice' ? (a.score_rate ?? 1) - (b.score_rate ?? 1) : 0)
    || compareText(a.requirement['指标编号'] ?? '', b.requirement['指标编号'] ?? ''))
  const arranged: typeof priorities = []
  for (const priorityRank of [...new Set(priorities.map(rank))]) {
    const group = priorities.filter(priority => rank(priority) === priorityRank)
    if (group.every(priority => priority.kind !== 'targeted_practice')) {
      const topicGroups = new Map<string, typeof priorities>()
      for (const priority of group) {
        const topic = priority.requirement['主题编号'] ?? ''
        topicGroups.set(topic, [...(topicGroups.get(topic) ?? []), priority])
      }
      while ([...topicGroups.values()].some(values => values.length > 0)) {
        for (const values of topicGroups.values()) {
          const next = values.shift()
          if (next) arranged.push(next)
        }
      }
    } else arranged.push(...group)
  }
  const scopedRecords = dataset.current.filter(record => record.student_id === scope.student_id && record.node_id === scope.node_id)
  const validItems = new Set(valid.map(record => record.item_id))
  const blockedItems = new Set(scopedRecords.filter(record => record.grading_status === '待评分'
    || (reviewIds.has(record.record_id) && !validItems.has(record.item_id))).map(record => record.item_id))
  const attemptedItems = new Set(scopedRecords.filter(record => record.grading_status !== '未作答' || record.answer.trim() !== '' || record.steps.trim() !== '').map(record => record.item_id))
  for (const { requirement, kind, evidence, rationale, findings } of arranged) {
    const indicatorId = requirement['指标编号']!
    const topicId = requirement['主题编号']!
    const candidates = items.filter(item => item['指标编号'] === indicatorId && !blockedItems.has(item['材料编号']!)).sort((a, b) => compareText(a['材料编号'] ?? '', b['材料编号'] ?? ''))
    const partialItems = new Set(valid.filter(record => effectiveScore(record)! < effectiveMax(record)!).map(record => record.item_id))
    const locatedFinding = findings.find(finding => finding.indicator_id === indicatorId
      && finding.category === 'fact' && finding.step_refs.length > 0 && finding.item_id !== null)
    const unattempted = candidates.find(item => !attemptedItems.has(item['材料编号']!))
    const chosen = kind === 'targeted_practice'
      ? candidates.find(item => item['材料编号'] === locatedFinding?.item_id)
        ?? candidates.find(item => partialItems.has(item['材料编号']!)) ?? candidates[0]
      : unattempted ?? candidates[0]
    if (!chosen) {
      limitations.push(`指标${indicatorId}当前仅有待评分或待复核题目，先核对这些记录；未重复安排同题或编造新题。`)
      continue
    }
    const chosenId = chosen['材料编号']!
    const specificFinding = kind === 'targeted_practice' ? locatedFinding?.item_id === chosenId ? locatedFinding
      : findings.find(finding => finding.item_id === chosenId && finding.category === 'fact') : undefined
    const selectionReason: LearningActivity['selection_reason'] = kind === 'targeted_practice' ? locatedFinding?.item_id === chosenId ? 'diagnosed_error' : 'partial_score'
      : unattempted ? 'unattempted_item' : 'explanation_check'
    const matchingLossEvidence = valid.filter(record => record.item_id === chosenId && effectiveScore(record)! < effectiveMax(record)!).map(record => record.record_id)
    const activityEvidence = specificFinding ? specificFinding.evidence_ids
      : kind === 'targeted_practice' && matchingLossEvidence.length > 0 ? matchingLossEvidence : evidence
    const curriculum = diagnosis.payload.curriculum.find(entry => entry.indicator_id === indicatorId)
    const materialIds = new Set(curriculum?.material_ids ?? [])
    for (const material of dataset.input.items) {
      if (material['材料类型'] === '学习卡' && material['主题编号'] === topicId
        && ids(material['指标编号']).includes(indicatorId)) materialIds.add(material['材料编号']!)
    }
    const availableMaterialIds = [...materialIds].filter(id => dataset.input.items.some(item => item['材料编号'] === id)).sort()
    const label = requirement['观察指标'] || indicatorId
    const activity: LearningActivity = {
      activity_id: `activity-${payload.activities.length + 1}`, order: payload.activities.length + 1, kind,
      phase: payload.activities.length < payload.delivery.first_batch_limit ? 'first' : 'follow_up', selection_reason: selectionReason,
      finding_ids: specificFinding ? [specificFinding.finding_id] : [],
      goal: selectionReason === 'diagnosed_error' ? `先核对原作答第${specificFinding!.step_refs.join('、')}步：${label}`
        : kind === 'targeted_practice' ? `核对并巩固：${label}` : kind === 'extension' ? `解释并检验：${label}` : `补充观察：${label}`,
      indicator_id: indicatorId, topic_id: topicId, item_ids: [chosen['材料编号']!], material_ids: availableMaterialIds,
      evidence_ids: activityEvidence, rationale: specificFinding?.description ?? rationale,
      prompt: selectionReason === 'diagnosed_error' ? `先回到原作答第${specificFinding!.step_refs.join('、')}步，说明这一步对两边做了什么运算、应使用哪条性质；再独立修正后续步骤并检查，不先照抄完整答案。`
        : kind === 'extension' ? selectionReason === 'explanation_check' ? '所列题目已有有效作答；本轮不只重填答案，请解释原步骤成立的理由，再用另一种方法检验或提出一个条件变化并说明影响。'
          : '先独立完成同指标尚未尝试的题目，再解释每一步依据，用另一种检查方法检验结果。'
        : kind === 'observation' ? '先独立完成所列题目并保留步骤；需要提示时说明使用到哪一级，供教师区分独立完成与借助提示完成。'
          : '先对照已有作答核对失分位置，再完成所列练习；每次只看一级提示，保留修正前后的步骤。',
      observation: guidance_for(indicatorId).observation.join('；'),
      adjust_when: guidance_for(indicatorId).adjustment.join(''),
      success_criteria: [...guidance_for(indicatorId).success_criteria],
      next_if_success: kind === 'extension' ? '记录解释和检验证据；若仍稳定，再由教师选择新的同范围任务。'
        : kind === 'observation' ? '再补一题同指标变式；仍能独立完成后才记为初步掌握。'
          : '减少提示层级，完成同指标变式并说明依据。',
      next_if_not: kind === 'extension' ? '保留本次证据并重新诊断；针对首次卡点安排同结构任务。'
        : kind === 'observation' ? '记录提示层级与卡点，进入该指标的小步辅导。'
          : '回到对应学习卡，降低一个认知步骤并保留新作答供教师调整。',
    }
    payload.activities.push(activity)
  }
  payload.delivery.first_activity_ids = payload.activities.filter(activity => activity.phase === 'first').map(activity => activity.activity_id)
  payload.delivery.follow_up_activity_ids = payload.activities.filter(activity => activity.phase === 'follow_up').map(activity => activity.activity_id)
  if (payload.activities.length === 0) limitations.push('当前节点缺少可用于已教指标的实际题目，未编造题目或学习资源。')
  if (reviewIds.size > 0) limitations.push('待复核评分未作为薄弱或成功表现的活动依据，应先由教师核对原始记录。')
  if ([...reviewIds].some(id => !stats.payload.review_record_ids.includes(id))) limitations.push('statistics保留数据层初步统计；其中诊断新发现的评分争议已从活动依据排除，不可依据该初步汇总形成能力判断。')
  if (valid.length > 0 && planType === 'observation') limitations.push('已有有效表现仍保留；观察计划针对尚无记录的已教范围，不否定已观察到的表现。')
  const status = stats.result_status === 'needs_review' || diagnosis.result_status === 'needs_review' ? 'needs_review'
    : payload.activities.length === 0 || planType === 'observation' ? 'insufficient_data' : 'ok'
  return result(dataset, { ...scope }, payload, status, stats.evidence_ids, limitations)
}

/**
 * Provide progressive method hints without copying final answers into student output.
 * @param dataset - Prepared source snapshot with question, node and scoring references.
 * @param request - Student, node, question, hint level and explicit presentation mode.
 * @returns Method guidance, or a teacher-only source solution when explicitly requested.
 */
export function get_hint(dataset: PreparedDataset, request: HintRequest): ResultEnvelope<HintPayload> {
  const mode = request.mode ?? 'student'
  const payload: HintPayload = {
    engine: 'local_rules', mode, student_id: request.student_id, node_id: request.node_id,
    item_id: request.item_id, level: request.level, hint: '', requires_review: false,
  }
  const scope = { student_id: request.student_id, node_id: request.node_id, item_id: request.item_id, mode, level: String(request.level) }
  const student = dataset.input.students.find(row => row['学生编号'] === request.student_id)
  const node = dataset.input.nodes.find(row => row['节点编号'] === request.node_id)
  const item = dataset.input.items.find(row => row['材料编号'] === request.item_id && row['材料类型'] === '题目')
  if (!student || !node || !item || ![1, 2, 3].includes(request.level) || !['student', 'teacher'].includes(mode)) {
    return result(dataset, scope, payload, 'error', [], ['学生、节点、题目、提示级别或模式无效，未生成提示。'])
  }
  if (!ids(node['可用题目编号']).includes(request.item_id) || !ids(node['已教及测量主题']).includes(item['主题编号'] ?? '')) {
    return result(dataset, scope, payload, 'error', [], ['题目不属于指定节点的已教和允许题集，未将未教内容当作薄弱项。'])
  }
  const evidence = dataset.current.filter(record => record.student_id === request.student_id && record.node_id === request.node_id && record.item_id === request.item_id)
  payload.requires_review = evidence.some(record => record.action === 'review')
  const requirement = dataset.input.requirements.find(row => row['指标编号'] === item['指标编号'])
  payload.hint = focusedHint(item, requirement, request.level)
  if (mode === 'teacher') {
    payload.teacher_solution = { reference_answer: item['参考答案'] ?? '', reference_analysis: item['参考解析'] ?? '', scoring_rubric: item['评分点'] ?? '' }
  } else {
    const answer = item['参考答案'] ?? ''
    if (hint_leaks_answer(payload.hint, answer)) {
      payload.hint = '请标记你准备使用的条件，写出每一步理由，并请教师核对。'
      if (hint_leaks_answer(payload.hint, answer)) {
        payload.hint = ''
        return result(dataset, scope, payload, 'needs_review', evidence.map(record => record.record_id), ['通用提示与参考答案存在文本重合，已隐藏提示，需教师补充。'])
      }
    }
  }
  const limitations = ['本提示为本地方法规则，未计算新的答案；使用提示后应保留实际帮助等级。']
  if (mode === 'teacher') limitations.push('教师展示模式用于本地演示，尚不提供账号鉴权；部署前须由调用方限制访问。')
  if (payload.requires_review) limitations.push('该题评分存在待复核问题，提示仅为通用方法，不据此断言学生存在知识漏洞。')
  return result(dataset, scope, payload, payload.requires_review ? 'needs_review' : 'ok', evidence.map(record => record.record_id), limitations)
}
